package com.eatwhat.service;
import com.eatwhat.entity.*;import com.eatwhat.mapper.*;import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.ObjectNode;import org.junit.jupiter.api.Test;import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class DietNutritionBoundaryTest {
 ObjectMapper json=new ObjectMapper();
 Dish dish(int kcal,String completeness){Dish d=new Dish();d.setId(9L);d.setName("面");d.setType("staple");ObjectNode recipe=json.createObjectNode();recipe.put("baseServings",2);ObjectNode n=recipe.putObject("calculatedNutrition");n.put("scope",CanonicalRecipeCalculator.NUTRITION_SCOPE);n.put("completeness",completeness);ObjectNode total=n.putObject("total");for(String key:CanonicalRecipeCalculator.NUTRIENTS)total.put(key,kcal);d.setRecipe(recipe);return d;}
 RecipeRecord record(String day,Dish...dishes){RecipeRecord r=new RecipeRecord();r.setUserId(1L);r.setRecordDateString(day);r.setMealType("dinner");r.setRecipeName("一餐");r.setDishDetails(Arrays.asList(dishes));return r;}
 @Test void serverOwnedRecipeSnapshotBeatsForgedClientNutrition() throws Exception {RecipeRecordMapper db=mock(RecipeRecordMapper.class);DishQueryService catalog=mock(DishQueryService.class);when(catalog.getDishesByIdsForUser(Arrays.asList(9L),1L)).thenReturn(Arrays.asList(dish(10,"complete")));RecipeRecord incoming=json.readValue("{\"recordDateString\":\"2026-01-01\",\"mealType\":\"dinner\",\"recipeName\":\"面\",\"dishIds\":[9],\"dishDetails\":[{\"id\":9,\"recipe\":{\"calculatedNutrition\":{\"total\":{\"energyKcal\":999}}}}]}",RecipeRecord.class);incoming.setUserId(1L);new RecipeRecordService(db,catalog).saveRecipeRecord(incoming);Map<?,?> n=(Map<?,?>)MealRecordProjection.from(incoming).getActualDishes().get(0).get("nutritionSnapshot");assertEquals(10,((Number)((Map<?,?>)n.get("total")).get("energyKcal")).intValue());}
 @Test void observedRecordNutritionPreservesPartialTotalsAndIgnoresFutureAndDeleted(){Dish free=new Dish();free.setName("外食");RecipeRecord deleted=record("2026-01-02",dish(888,"complete"));deleted.setIsDeleted(true);Map<String,Object> report=new DietReviewCalculator(json).report(1L,Collections.emptyList(),Arrays.asList(record("2026-01-01",dish(10,"complete"),dish(500,"partial"),free),deleted,record("2026-01-04",dish(999,"complete"))),LocalDate.parse("2026-01-01"),LocalDate.parse("2026-01-04"),Instant.parse("2026-01-03T04:00:00Z"));Map<?,?> n=(Map<?,?>)((Map<?,?>)((Map<?,?>)report.get("blocks")).get("actualDetails")).get("nutrition");assertEquals(3,n.get("entryCount"));assertEquals(1,n.get("coveredCount"));assertEquals(2,n.get("unknownCount"));assertNull(n.get("total"));assertEquals(false,n.get("personalIntakeAvailable"));assertEquals(10,((Number)((Map<?,?>)n.get("knownTotal")).get("energyKcal")).intValue());}
}
